#include <iostream>
#include <string>
#include <string_view>
#include <vector>

// Demonstrating Good Practice & Portability: explicit fixed types and RAII
class CurriculumModule {
private:
    std::string name;
    int chapterNumber;

public:
    // Performance Tip: Pass by value + std::move or pass by const ref
    CurriculumModule(std::string_view moduleName, int chapter)
        : name(moduleName), chapterNumber(chapter) {}

    // Const-correctness (Good Practice & Error Prevention)
    [[nodiscard]] int getChapterNumber() const noexcept {
        return chapterNumber;
    }

    [[nodiscard]] std::string_view getName() const noexcept {
        return name;
    }
};

int main() {
    // Building a modern dependency trace analogous to Deitel's chart
    std::vector<CurriculumModule> roadmap;
    roadmap.reserve(3); // Performance Tip: Pre-allocate capacity

    roadmap.emplace_back("Intro to C Programming", 2);
    roadmap.emplace_back("C Pointers and Arrays", 6);
    roadmap.emplace_back("C++ Classes and Objects", 16);

    for (const auto& module : roadmap) {
        std::cout << "Chapter " << module.getChapterNumber() 
                  << ": " << module.getName() << "\n";
    }

    return 0;
}
